     currency: z.string().length(3),
     feeBearer: z.enum(["PAYER", "MERCHANT", "PLATFORM", "MERCHANT_ABSORBS", "PAYER_SURCHARGE", "SPLIT"]).optional(),
     applicationId: z.string().min(1).max(64).optional(),
     walletId: z.string().min(1).max(64).optional(),
