 function ipv4Number(address: string): number | undefined {
   const parts = address.split(".");
   if (parts.length !== 4) {
     return undefined;
   }
   let result = 0;
   for (const part of parts) {
     if (!/^\d{1,3}$/.test(part)) {
       return undefined;
     }
     const octet = Number(part);
     if (octet > 255) {
       return undefined;
     }
     result = result * 256 + octet;
   }
   return result;
 }

