const readSecretFile = (label: string, filePath: string): Buffer => {
  try {
    return fs.readFileSync(filePath);
  } catch {
    throw new Error(
      `Unable to read ${label} from '${filePath}'. Run 'bun run generate-mtls-certs' before starting core-back.`,
    );
  }
};

/**
 * Endpoints that carry opaque binary payloads (gateway webhooks, KYB
 * documents, statement files) must receive the exact bytes that were sent:
 * a JSON body parser would consume them and destroy the signature material.
 * The raw collector is therefore mounted before the JSON parser.
 */
const RAW_BODY_PATHS = [
  "/internal/checkout/inbound",
  "/internal/merchant/onboarding/kyb-documents",
  "/internal/admin/reconciliation/upload",
];

const rawBodyCollector = express.raw({
  type: () => true,
  limit: "25mb",
});

const rawBodyMiddleware = (request: Request, response: Response, next: NextFunction): void => {
  const matches = RAW_BODY_PATHS.some((path) => request.path === path || request.path.startsWith(`${path}/`));
  if (!matches) {
    next();
    return;
  }
  rawBodyCollector(request, response, next);
};

export const createApp = () => {
  const app = express();
  app.disable("x-powered-by");
  app.set("trust proxy", env.TRUST_PROXY);
  app.use(requestIdMiddleware);
  app.use(requestLoggerMiddleware);
  app.use(rawBodyMiddleware);
  app.use(express.json({ limit: "1mb" }));
  app.use(express.urlencoded({ extended: true, limit: "1mb" }));

