+export interface DayWindow {
+  since: Date;
+  until: Date;
+}
+
+const zoneFormatterCache = new Map<string, Intl.DateTimeFormat>();
+
+const zoneFormatter = (timeZone: string): Intl.DateTimeFormat | null => {
+  const cached = zoneFormatterCache.get(timeZone);
+  if (cached) {
+    return cached;
+  }
