 function isUniqueConstraintError(error: unknown): boolean {
   if (!error || typeof error !== "object") {
     return false;
   }
   const code = (error as { code?: unknown }).code;
   return code === "P2002" || code === "UNIQUE_CONSTRAINT_VIOLATION";
 }

