                 pathToken: z.string().min(8).max(120),
                 verifyMethod: z.enum([
                   "HMAC_BODY",
                   "HASH_FIELDS",
                   "SORTED_VALUES_HASH",
                   "RSA",
                   "SHARED_TOKEN",
                   "IP_ONLY",
                   "NONE_PLUS_INQUIRY",
                 ]),
                 signatureHeader: z.string().max(120).optional(),
