   if (selector) {
     const value = recursiveSelect(payload, selector);
     if (typeof value === "string" || typeof value === "number") {
       return String(value);
     }
   }
   for (const path of fallback) {
     const value = recursiveSelect(payload, path);
     if (typeof value === "string" || typeof value === "number") {
