     .replaceAll("YYYY", parts.year ?? "")
     .replaceAll("MM", parts.month ?? "")
     .replaceAll("DD", parts.day ?? "")
     .replaceAll("HH", parts.hour ?? "")
     .replaceAll("mm", parts.minute ?? "")
     .replaceAll("ss", parts.second ?? "")
     .replaceAll("SSS", milliseconds);
