   }
   const updated = await client.paymentAttempt.update({
     where: { id: attempt.id },
     data: { lastOtpSentAt: new Date(), otpAttempts: attempt.otpAttempts },
   });
   response.json({ attemptId: updated.id, status: updated.status, resendAvailableInSeconds: cooldown });
 });

