     );
     return Number(result ?? 0) > 0;
   }

   private async releaseSlot(attempt: PaymentAttemptRow): Promise<void> {
     if (!attempt.linkId) return;
     try {
       await this.repositories.payments.updateLinkSlotCount(this.db as Tx, attempt.linkId, -1);
     } catch (error) {
