   const before = listMigrationDirectories();
   runPrisma([
     "migrate",
     "dev",
     "--create-only",
     "--name",
     "init",
     `--schema=${schemaPath}`,
   ]);
   const after = listMigrationDirectories();
   const created = after.filter((directory) => !before.includes(directory));
