cd /home/salem/payment-gateway/core-back && python3 - <<'PY'
import pathlib

# 1. the Prisma client uses the MariaDB adapter
p = pathlib.Path("prisma/client/base.ts")
p.write_text('''import { PrismaMariaDb } from "@prisma/adapter-mariadb";
import { PrismaClient } from "../../generated/prisma/client";
import { env } from "../../lib/env";

let baseClientInstance: PrismaClient | undefined;

export const createBaseClient = (): PrismaClient =>
  new PrismaClient({
    adapter: new PrismaMariaDb(env.DATABASE_URL),
    log: [],
  });

export const getBaseClient = (): PrismaClient => {
  if (!baseClientInstance) {
    baseClientInstance = createBaseClient();
  }
  return baseClientInstance;
};
''')
print("base.ts ok")

# 2. the environment validates a MySQL/MariaDB connection string
p = pathlib.Path("lib/env/index.ts")
t = p.read_text()
old = '''const postgresUrl = z
  .string()
  .min(1, "DATABASE_URL is required")
  .refine((value) => /^postgres(?:ql)?:\\/\\//i.test(value), "DATABASE_URL must be a PostgreSQL URL");'''
new = '''const mysqlUrl = z
  .string()
  .min(1, "DATABASE_URL is required")
  .refine(
    (value) => /^mysql:\\/\\//i.test(value),
    "DATABASE_URL must be a MySQL/MariaDB URL (mysql://user:password@host:port/database)",
  );'''
assert old in t, "env url"
t = t.replace(old, new)
t = t.replace("  DATABASE_URL: postgresUrl,", "  DATABASE_URL: mysqlUrl,")
t = t.replace(
  '    DATABASE_URL: "postgresql://postgres:postgres@127.0.0.1:5432/payment_gateway",',
  '    DATABASE_URL: "mysql://gateway:gateway_pw@127.0.0.1:3307/payment_gateway",',
)
p.write_text(t)
print("env ok")

# 3. the prisma config uses the same default
p = pathlib.Path("prisma7.config.ts")
t = p.read_text()
t = t.replace(
  '  process.env.DATABASE_URL ?? "postgresql://postgres:postgres@127.0.0.1:5432/payment_gateway";',
  '  process.env.DATABASE_URL ?? "mysql://gateway:gateway_pw@127.0.0.1:3307/payment_gateway";',
)
p.write_text(t)
print("config ok")
PY
grep -n "mysqlUrl\|mysql://" lib/env/index.ts prisma7.config.ts | head

