import re, pathlib
sql = pathlib.Path("/tmp/opencode/mysql3.sql").read_text()
# column types per table
cols = {}
for m in re.finditer(r"CREATE TABLE `(\w+)` \((.*?)\n\) ENGINE", sql, re.S):
    table, body = m.group(1), m.group(2)
    cols[table] = {}
    for line in body.split("\n"):
        cm = re.match(r"\s+`(\w+)`\s+([A-Z]+)", line)
        if cm:
            cols[table][cm.group(1)] = cm.group(2)
# foreign keys
bad = []
for m in re.finditer(r"ALTER TABLE `(\w+)` ADD CONSTRAINT `(\w+)` FOREIGN KEY \(`(\w+)`\) REFERENCES `(\w+)`\(`(\w+)`\)", sql):
    child, _, child_col, parent, parent_col = m.groups()
    ct = cols.get(child, {}).get(child_col)
    pt = cols.get(parent, {}).get(parent_col)
    if ct in ("TEXT", "LONGTEXT", "MEDIUMTEXT", "TINYTEXT", "BLOB", "LONGBLOB") or pt in ("TEXT", "LONGTEXT", "MEDIUMTEXT", "TINYTEXT", "BLOB", "LONGBLOB"):
        bad.append((child, child_col, ct, parent, parent_col, pt))
print("FK columns on a TEXT/BLOB type:", len(bad))
for b in bad:
    print("  ", b)
PY

