   const envelope = parseCoreEnvelope(payload);
   const fallback = STATUS_FALLBACKS[statusCode] ?? {
     code: "CORE_ERROR",
     message: `Core service returned status ${statusCode}`,
   };
   return new ApiError(
     statusCode,
     envelope?.code ?? fallback.code,
     envelope?.message ?? fallback.message,
     envelope?.details,
     envelope?.reference,
   );
 };

