+        // point at the journal entries and at the disputes, so they have to
+        // be gone before their parents are removed.
+        summary.journalLines += await this.purgeRows(
+          tx,
+          "journal_lines",
+          "`entry_id` IN (" + mysqlPlaceholders(entryIds.length) + ")",
+          entryIds,
+        );
