+      return 0;
+    }
+    if (this.dryRun) {
+      return this.countRows(tx, `SELECT COUNT(*) AS \`total\` FROM \`${table}\` WHERE ${predicate}`, params);
+    }
+    let total = 0;
+    for (;;) {
+      const affected = Number(
+        await tx.$executeRawUnsafe(
+          `DELETE FROM \`${table}\` WHERE ${predicate} LIMIT ?`,
+          ...params,
+          this.batchSize,
+        ) ?? 0,
+      );
+      total += affected;
+      if (affected < this.batchSize) {
+        return total;
+      }
+    }
+  }
