 const toBuffer = (value: unknown): Buffer => {
   if (Buffer.isBuffer(value)) {
     return value;
   }
   if (value instanceof Uint8Array) {
     return Buffer.from(value);
   }
   if (typeof value === "string") {
     return Buffer.from(value, "base64");
   }
   return Buffer.alloc(0);
 };

