+    let count = false;
+    const columns: string[] = [];
+    if (this.peek() === "COUNT") {
+      this.next();
+      this.expect("(");
+      this.expect("*");
+      this.expect(")");
+      if (this.peek() === "AS") {
+        this.next();
+        this.next();
+      }
+      count = true;
+    } else {
+      columns.push(this.next());
+      while (this.peek() === ",") {
+        this.next();
+        columns.push(this.next());
+      }
+    }
+    this.expect("FROM");
+    const table = this.next();
+    let where: Condition | undefined;
+    if (this.peek() === "WHERE") {
+      this.next();
+      where = this.parseCondition();
+    }
+    let orderBy: { column: string; descending: boolean } | undefined;
+    if (this.peek() === "ORDER") {
+      this.next();
+      this.expect("BY");
+      const column = this.next();
+      let descending = false;
+      if (this.peek() === "DESC") {
+        this.next();
+        descending = true;
+      } else if (this.peek() === "ASC") {
