+  private parseFactor(): Condition {
+    if (this.peek() === "(") {
+      this.next();
+      const condition = this.parseCondition();
+      this.expect(")");
+      return condition;
+    }
+    const column = this.next();
+    let operator = this.next();
+    if (operator === "NOT" && this.peek() === "IN") {
+      this.next();
+      operator = "NOT IN";
+    }
+    if (operator === "IS") {
+      const second = this.next();
+      if (second === "NOT") {
