+  /** The Prisma client the worker talks to. */
+  db: PrismaLike;
+  /** The rows of a table. */
+  rows(table: string): FakeRow[];
+  /** Puts rows into a table. */
+  seed(table: string, rows: FakeRow[]): void;
+  /** Empties every table. */
