 const amlActionOf = (payload: unknown): AmlCaseAction => {
   const record = asRecord(payload);
   const action = String(record.action ?? "RELEASE").toUpperCase();
   if (action === "HOLD" || action === "RELEASE" || action === "REJECT" || action === "ESCALATE") {
     return action;
   }
