+              updated_at = NOW()
+        WHERE id = ?`,
+      linkId,
+    );
+    return;
+  }
+  const links = modelOf(tx, "paymentLink");
+  const link = await links.findUnique({ where: { id: linkId } });
+  if (!link) {
+    return;
+  }
+  const active = linkCountOf(link, "activeLockedCount", "active_locked_count");
