         severityRank(CONFIRMED_MATCH_SEVERITY[listType] ?? "HIGH") > severityRank(worst)
           ? CONFIRMED_MATCH_SEVERITY[listType] ?? "HIGH"
           : worst,
       "MEDIUM",
