       consumer = await this.options.consumerRegistry.getConsumer({
         gatewayId,
         env,
         credentialSetId,
         gatewayVersionId,
       });
     } catch (error) {
       return this.record(credentialSetId, {
         ...base,
         status: "FAILING",
         reason: error instanceof Error ? error.message : "The outbound consumer could not be built",
