             param("BODY", "reference", "ATTEMPT", { selector: "reference" }),
           ],
           outputs: [
             output("payment_uuid", "payment_uuid", "STATE", true),
             output("pay_code", "pay_code", "PUBLIC"),
             output("qr_payload", "qr.payload", "PUBLIC"),
           ],
         }),
         step({
           name: "show-otp-or-qr",
           type: "RENDER",
           method: "SHOW_QR_OR_CODE",
           sideEffect: "READ_ONLY",
