                   param("QUERY", "reference", "ATTEMPT", { selector: "reference" }),
                 ],
                 outputs: [
                   output("status", "status", "STATE", true),
                   output("settled_amount", "amount", "SETTLED_AMOUNT"),
                   output("provider_reference", "bank_reference", "PROVIDER_REF"),
                 ],
