         this.expect(")");
         return { kind: "subquery", statement };
       }
       const start = this.paramIndex;
       let length = 0;
       while (this.peek() !== ")") {
         this.expect("?");
         this.paramIndex += 1;
         length += 1;
         if (this.peek() === ",") {
           this.next();
         }
       }
       this.expect(")");
       return { kind: "list", start, length };
     }
