+
+const NOW = new Date("2026-06-01T00:00:00.000Z");
+
+const rule = (overrides: Partial<ReportingRuleRecord> = {}): ReportingRuleRecord => ({
+  id: "rule-large-transaction",
+  authority: "CBL",
+  reportType: "LARGE_TRANSACTION",
+  thresholdAmount: "50000.0000",
+  windowSeconds: null,
