 const recordingLogger = (): WorkerLogger & { lines: string[] } => {
   const lines: string[] = [];
   return {
     lines,
     info: (message, meta) => {
       lines.push(`${message} ${JSON.stringify(meta ?? {})}`);
     },
     warn: (message, meta) => {
