     },
     error: (message, meta) => {
       lines.push(`${message} ${JSON.stringify(meta ?? {})}`);
     },
   };
 };

 const buildWorker = (
   fake: ReturnType<typeof createRetentionFake>,
   options: { dryRun?: boolean; retentionDays?: number } = {},
 ) => {
