     bodyFormat: "JSON",
     correlationSelector: "reference",
     dedupeKeySelector: "event_id",
     eventMap: { "00": "SUCCESS" },
     mustInquire: false,
     ackStatus: 200,
     ackBodyTemplate: null,
     cryptoProfile: {
       id: "crypto-1",
       algorithm: "HMAC_SHA256",
       secretKeyEncoding: "UTF8",
       canonicalizationMode: "RAW_BODY",
       outputEncoding: "HEX_LOWER",
     },
   };

   const credentialSet = {
